<include file="Public:header"/>	<div class="mainbox">		<!-- <div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('Merchant_bill/index')}" class="on">商家对账</a>			</ul>		</div> -->		<table class="search_table" width="100%">			<tr>				<td style="width:60%;">					退款订单列表									<!-- 	<a  href="javascript:void(0)" onclick="doBill()" class="button  " style=" color: #fff;background: #1890FF;border: solid 1px #1890FF;">确认对账</a>					<a  href="javascript:void(0)" onclick="exports()" class="button" style="margin-left: 10px;">导出</a> -->															</td>			</tr>		</table>					<div class="table-list">				<table width="100%" cellspacing="0">					<colgroup><col> <col> <col><col width="240" align="center"> </colgroup>					<thead>						<tr>							<th>店铺名称</th>							<th>订单号</th>							<th>订单类型</th>							<th>退款金额</th>							<th>下单时间</th>							<!-- <th>支付时间</th> -->						</tr>					</thead>					<tbody>						<if condition="is_array($list)">							<volist name="list" id="vo">								<tr>									<td>{pigcms{$vo.store_name|default="--"}</td>									<td>{pigcms{$vo.real_orderid}</td>									<td>{pigcms{$vo.business_name}</td>									<td>{pigcms{$vo.refund_money}</td>									<td>{pigcms{$vo.create_time|date='Y-m-d H:i:s',###}</td>									<!-- <td>										<if condition="$vo['pay_time']">											{pigcms{$vo.pay_time|date='Y-m-d H:i:s',###}										<else/>											--										</if>									</td> -->								</tr>							</volist>							<!-- <tr><td class="textcenter pagebar" colspan="5">{pigcms{$pagebar}</td></tr> -->						<else/>							<tr><td class="textcenter red" colspan="5">列表为空！</td></tr>						</if>					</tbody>				</table>			</div>	</div><include file="Public:footer"/>